        let fd1 = table.open_read(tmp1.path().to_str().unwrap()).unwrap();
        let fd2 = table.open_read(tmp2.path().to_str().unwrap()).unwrap();
        assert_ne!(fd1, fd2);

        let b1 = table.read_byte(fd1).unwrap();
